const cfg = $('⚙️ CONFIG').first().json;
const cloth_id = $input.first().json.body.cloth_id;
const sbh = { apikey: cfg.SB_KEY, Authorization: `Bearer ${cfg.SB_KEY}`, 'Content-Type': 'application/json' };

// 1. Récupérer la commande complète avec son support
const clothRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth_id}&select=*,totehm_cloth_support(*)`,
  headers: sbh, json: true
});
const cloth = clothRes[0];
const support = cloth.totehm_cloth_support;

// 2. Mapper taille → sync_variant_id via printful_variant_map
const variantMap = support.printful_variant_map;
if (!variantMap || !variantMap[cloth.size]) {
  throw new Error(`Taille ${cloth.size} introuvable dans printful_variant_map pour le support ${support.id}`);
}
const sync_variant_id = variantMap[cloth.size].sync_variant_id;

// 3. Lire la méthode d'impression depuis print_area
const printArea = support.print_area || { method: 'dtg', placement: 'back' };
const fileType = printArea.method === 'dtg' ? 'back' : `embroidery_${printArea.placement}`;

// 4. Construire le payload Printful
const pfOrder = {
  recipient: {
    name: cloth.shipping?.name || 'TOTEHM Client',
    address1: cloth.shipping?.address?.line1,
    address2: cloth.shipping?.address?.line2 || '',
    city: cloth.shipping?.address?.city,
    state_code: cloth.shipping?.address?.state || '',
    country_code: cloth.shipping?.address?.country,
    zip: cloth.shipping?.address?.postal_code
  },
  items: [{
    sync_variant_id: sync_variant_id,
    name: `TOTEHM — ${cloth.name}`,
    quantity: 1,
    files: [{
      type: fileType,
      url: cloth.artwork_print_url
    }]
  }]
};

// 5. Envoyer à Printful
const pf = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.printful.com/orders',
  headers: { Authorization: `Bearer ${cfg.PRINTFUL_TOKEN}`, 'Content-Type': 'application/json' },
  body: pfOrder, json: true
});

// 6. Mettre à jour Supabase
await this.helpers.httpRequest({
  method: 'PATCH',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth_id}`,
  headers: sbh, json: true,
  body: { status: 'production', printful_order_id: pf.result.id }
});

return [{ json: { ok: true, printful_order_id: pf.result.id, file_type: fileType, sync_variant_id } }];
